/* ---------- Medição ---------- */
window.dataLayer=window.dataLayer||[];
function track(ev,p={}){
  try{dataLayer.push({event:ev,...p});}catch(e){}
  try{window.fbq&&fbq('trackCustom',ev,p);}catch(e){}
  try{window.gtag&&gtag('event',ev,p);}catch(e){}
}
