/* ---------- Horário de Teresina e pílula ---------- */
function nowTz(){
  const f=new Intl.DateTimeFormat('en-US',{timeZone:CONFIG.tz,weekday:'short',hour:'numeric',minute:'numeric',hour12:false}).formatToParts(new Date());
  const g=t=>f.find(x=>x.type===t).value, map={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
  return{d:map[g('weekday')],m:(+g('hour')%24)*60+(+g('minute'))};
}
function statusNow(){
  const {d,m}=nowTz(), today=OPEN[d]||[];
  for(const [a,b] of today){if(m>=a&&m<b)return{open:true,txt:`Aberto agora, até ${fmtMin(b)}`}}
  for(const [a] of today){if(m<a)return{open:false,txt:`Fechado, abre hoje ${fmtMin(a)}`}}
  for(let i=1;i<=7;i++){const dd=(d+i)%7;if(OPEN[dd]){const a=OPEN[dd][0][0];return{open:false,txt:`Fechado, abre ${i===1?'amanhã':DAYL[dd]} ${fmtMin(a)}`}}}
  return{open:false,txt:'Fechado'};
}
function dayRow(d){return OPEN[d].map(([a,b])=>`${fmtMin(a)} às ${fmtMin(b)}`).join(' e ')}
(function pill(){
  const pill=$('#pill'),t=$('#pillt'),bd=$('#board'),ul=$('#boardl');
  function upd(){const s=statusNow();t.textContent=s.txt;pill.classList.toggle('off',!s.open);const d=nowTz().d;ul.innerHTML=[1,2,3,4,5].map(x=>`<li class="${x===d?'today':''}"><span>${DAYS[x]}</span><span>${dayRow(x)}</span></li>`).join('')}
  upd();setInterval(upd,60000);
  const tog=v=>{const o=v!==undefined?v:bd.hidden;bd.hidden=!o;pill.setAttribute('aria-expanded',String(o));if(o)track('abrir_horarios')};
  pill.addEventListener('click',e=>{e.stopPropagation();tog()});
  $('#btn-hor').addEventListener('click',e=>{e.stopPropagation();tog(true)});
  document.addEventListener('pointerdown',e=>{if(!bd.hidden&&!bd.contains(e.target)&&e.target!==pill&&!pill.contains(e.target)&&e.target.id!=='btn-hor'&&!e.target.closest('#btn-hor'))tog(false)});
})();

/* ---------- Poeira de magnésio (ambiente, bem sutil, sem reação ao toque) ---------- */
const Dust=(function(){
  const cv=$('#dust'),cx=cv.getContext('2d');let W,H,dpr=Math.min(2,devicePixelRatio||1),ps=[],dark=true;
  const COLS=['227,206,233','227,206,233','227,206,233','238,205,96','102,142,142','210,80,67'];
  function size(){W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;cx.setTransform(dpr,0,0,dpr,0,0)}
  size();addEventListener('resize',size);
  for(let i=0;i<22;i++)ps.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.12,vy:-Math.random()*.18-.04,r:Math.random()*2+1.5,a:Math.random()*.3+.15,c:Math.floor(Math.random()*COLS.length)});
  function frame(){
    cx.clearRect(0,0,W,H);
    for(const p of ps){p.x+=p.vx;p.y+=p.vy;if(p.y<-8){p.y=H+8;p.x=Math.random()*W}if(p.x<-8)p.x=W+8;if(p.x>W+8)p.x=-8;
      cx.fillStyle=`rgba(${p.c>2||dark?COLS[p.c]:'120,66,135'},${(dark?p.a:p.a*.8).toFixed(2)})`;cx.fillRect(p.x,p.y,p.r,p.r)}
    requestAnimationFrame(frame)
  }
  if(!REDUCED)requestAnimationFrame(frame);
  return{setDark:d=>{dark=d}};
})();

