const Opening=(function(){
  const ov=$('#open'),cv=$('#oc'),cx=cv.getContext('2d'),hint=$('#ohint');
  const PAL=['249,245,250','238,205,96','102,142,142','210,80,67'];
  let W,H,dpr=Math.min(2,devicePixelRatio||1),ps=[],phase='idle',vt=0,tForm=0,sweep=0,done=false,last={x:0,y:0,on:false},raf,prev=0;
  const size=()=>{W=innerWidth;H=innerHeight;cv.width=W*dpr;cv.height=H*dpr;cx.setTransform(dpr,0,0,dpr,0,0)};
  size();addEventListener('resize',size);
  function finish(){
    if(done)return;done=true;cancelAnimationFrame(raf);
    ov.classList.add('gone');document.body.classList.remove('is-locked');
    setTimeout(()=>{ov.remove();document.body.classList.add('ready');window.dispatchEvent(new Event('quintal:open'))},900);
    track('abertura_concluida');
  }
  $('#skip').addEventListener('click',e=>{e.stopPropagation();finish()});
  if(REDUCED){hint.textContent='';setTimeout(finish,700);return{}}
  // alvos pré-calculados do logo (sem ler pixels em tempo de execução)
  const sc=Math.min(W*.86,380)/LOGO.w,ox=(W-LOGO.w*sc)/2,oy=(H-LOGO.h*sc)/2-H*.03,n=LOGO.p.length/3;
  for(let k=0;k<n;k++){const tx=ox+LOGO.p[k*3]*2*sc,ty=oy+LOGO.p[k*3+1]*2*sc,ci=LOGO.p[k*3+2];
    ps.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.5,vy:(Math.random()-.5)*.5,r:2+Math.random()*.8,a:.4+Math.random()*.5,tx,ty,c:ci,k:.012+Math.random()*.02,d:Math.random()*500})}
  for(let k=0;k<700;k++)ps.push({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.5,vy:(Math.random()-.5)*.5,r:1.6+Math.random(),a:.2+Math.random()*.4,tx:null,ty:null,c:[0,0,1,2,3][k%5],k:0,d:0});
  function form(){
    if(phase!=='idle')return;phase='form';tForm=vt;hint.textContent='';
    ps.forEach(p=>{p.vx=(Math.random()-.5)*6;p.vy=-Math.random()*5});track('abertura_formar');
  }
  ov.addEventListener('pointerdown',e=>{if(e.target.closest('#skip'))return;last={x:e.clientX,y:e.clientY,on:true};if(phase==='idle')form();else if(phase==='ready'){sweep+=170;push(e.clientX,e.clientY,120)}});
  ov.addEventListener('pointermove',e=>{if(phase!=='ready')return;const x=e.clientX,y=e.clientY;if(last.on||e.pointerType==='mouse'){sweep+=Math.hypot(x-last.x,y-last.y);push(x,y,90)}last.x=x;last.y=y;if(sweep>520)finish()});
  ov.addEventListener('pointerup',()=>{last.on=false});
  function push(x,y,r){for(const p of ps){const dx=p.x-x,dy=p.y-y,d=Math.hypot(dx,dy);if(d<r&&d>0){const f=(r-d)/r*7;p.vx+=dx/d*f;p.vy+=dy/d*f-1.2}}}
  // o relógio só avança com a aba visível, então a abertura nunca passa sem ser vista
  function frame(now){
    cx.clearRect(0,0,W,H);vt+=Math.min(now-(prev||now),64);prev=now;
    if(phase==='idle'&&vt>1100)form();
    if(phase==='form'&&vt-tForm>2300){phase='ready';hint.textContent='Passe o dedo para soprar o pó'}
    if(phase!=='idle'&&vt-tForm>4600)finish();
    if(vt>14000)finish();
    const t=vt-tForm;
    for(const p of ps){
      if(phase==='idle'){p.x+=p.vx+Math.sin(now/1100+p.d)*.3;p.y+=p.vy+Math.cos(now/1300+p.d)*.2;if(p.x<0)p.x=W;if(p.x>W)p.x=0;if(p.y<0)p.y=H;if(p.y>H)p.y=0}
      else{
        if(p.tx!==null&&t>500+p.d){p.vx+=(p.tx-p.x)*p.k;p.vy+=(p.ty-p.y)*p.k;p.vx*=.86;p.vy*=.86}
        else{p.vx*=.96;p.vy=p.vy*.96+.02}
        p.x+=p.vx;p.y+=p.vy;if(p.tx===null&&t>1500)p.a*=.97;
      }
      cx.fillStyle=`rgba(${PAL[p.c]},${phase!=='idle'&&p.tx!==null&&t>1500?1:p.a})`;cx.fillRect(p.x,p.y,p.r,p.r);
    }
    if(!done)raf=requestAnimationFrame(frame);
  }
  raf=requestAnimationFrame(frame);
  return{};
})();

/* ---------- Revelações, menu, mascote ---------- */
const SECS=$$('.sec');
function initReveal(){
  const sel={
    '#inicio':[['.logo','rv-z'],['.lead','rv-bl'],['.sub','rv-up'],['.links li','rv-up'],['.ask','rv-bl']],
    '#treino':[['h2','rv-bl'],['.p','rv-up'],['.slider','rv-l'],['.q2','rv-up'],['.chips','rv-r'],['.sheet','rv-rot']],
    '#plano':[['h2','rv-bl'],['.prog','rv-l'],['.step.on','rv-z'],['.nav','rv-up']],
    '#dentro':[['h2','rv-bl'],['.p','rv-up'],['.strip','rv-r'],['h3','rv-l'],['.car','rv-up']],
    '#quem':[['h2','rv-bl'],['.pile','rv-rot'],['.pcap','rv-up'],['.who','rv-up']],
    '#pergunte':[['h2','rv-bl'],['.chat','rv-z'],['.qs','rv-up']],
    '#onde':[['h2','rv-bl'],['.route','rv-r'],['address','rv-up'],['.links li','rv-l'],['.foot','rv-bl']]
  };
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.12});
  Object.entries(sel).forEach(([s,l])=>l.forEach(([q,c])=>$$(q,$(s)).forEach((el,i)=>{el.classList.add('rv',c);el.style.transitionDelay=(i*70)+'ms';io.observe(el)})));
}
const Menu=(function(){
  const as=$$('#menu a'),ind=$('#mind'),nav=$('#menu');let cur=-1;
  function set(i){if(i===cur)return;cur=i;as.forEach((a,k)=>a.classList.toggle('on',k===i));ind.style.transform=`translateX(${i*nav.clientWidth/7}px)`;const s=SECS[i];Dust.setDark(/dark|vivid/.test(s.className));track('secao',{s:s.id})}
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)set(SECS.indexOf(e.target))}),{threshold:[.35,.6],rootMargin:'0px 0px -20% 0px'});
  SECS.forEach(s=>io.observe(s));set(0);
  addEventListener('resize',()=>{const c=cur;cur=-1;set(c)});
  as.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();$(a.getAttribute('href')).scrollIntoView({behavior:REDUCED?'auto':'smooth'})}));
  return{get cur(){return cur}};
})();

/* Mascote: o Q, nas bordas, em rota fixa */
const Mascot=(function(){
  const m=$('#mascot'),say=$('#msay'),im=$('img',m);let leg=0,anim=null,hide=false,started=false;
  const lanes=()=>{const W=innerWidth,H=innerHeight;return[{y:H-108,a:8,b:W-48,low:false},{y:46,a:W-48,b:8,low:true},{y:H-108,a:W-48,b:8,low:false},{y:46,a:8,b:W-48,low:true}]};
  function speak(txt,x,low){
    say.textContent=txt;m.classList.toggle('low',low);const w=say.offsetWidth;
    say.style.left=clamp(-w/2+20,-(x-8),innerWidth-8-x-w)+'px';say.classList.add('show');
  }
  function run(){
    if(!started)return;const L=lanes()[leg%4],dir=L.b>L.a?1:-1;im.style.scale=dir>0?'1 1':'-1 1';say.classList.remove('show');m.style.opacity=hide?0:1;
    anim=m.animate([{transform:`translate(${L.a}px,${L.y}px)`},{transform:`translate(${L.b}px,${L.y}px)`}],{duration:Math.abs(L.b-L.a)*32,easing:'linear',fill:'forwards'});
    if(hide)anim.pause();
    anim.onfinish=()=>{const sec=SECS[Math.max(0,Menu.cur)],ph=(sec.dataset.say||'').split('|').filter(Boolean);if(ph.length&&!hide)speak(ph[leg%ph.length],L.b,L.low);leg++;setTimeout(run,3200)};
  }
  function setHide(v){hide=v;m.style.opacity=v||!started?0:1;if(anim){v?anim.pause():anim.play()}if(v)say.classList.remove('show')}
  addEventListener('quintal:open',()=>{if(REDUCED)return;started=true;setTimeout(run,1200)});
  new IntersectionObserver(es=>es.forEach(e=>setHide(e.isIntersecting&&e.intersectionRatio>.3)),{threshold:[0,.3,.5]}).observe($('#plano'));
  addEventListener('resize',()=>{if(anim){anim.cancel();run()}});
  return{setHide};
})();

/* ---------- Vídeos preguiçosos ---------- */
const Vid=(function(){
  const io=new IntersectionObserver(es=>es.forEach(e=>{const v=e.target;if(!v.dataset.auto)return;if(e.isIntersecting&&e.intersectionRatio>.4){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{})}else v.pause()}),{threshold:[0,.4,.7],rootMargin:'120px'});
  return{watch(v){v.dataset.auto='1';io.observe(v)}};
})();
function mkMedia(m,cls){
  const el=document.createElement('div');el.className=cls;
  if(m.v){const v=document.createElement('video');v.muted=true;v.loop=true;v.playsInline=true;v.preload='none';v.poster=`assets/${m.f}.jpg`;v.dataset.src=`assets/${m.f}.mp4`;el.appendChild(v);Vid.watch(v)}
  else{const i=new Image();i.src=`assets/${m.f}.webp`;i.alt=m.c||'';i.loading='lazy';i.decoding='async';el.appendChild(i)}
  el.dataset.f=m.f;el.dataset.v=m.v?'1':'';el.dataset.c=m.c||'';return el;
}

/* ---------- Seu treino: objetivo, esporte e ficha ---------- */
(function(){
  const CHS=[
    {n:'Liberação com rolinho nas costas',k:'Liberação',t:0},{n:'Liberação miofascial',k:'Liberação',t:25},{n:'Ombro e antebraço com bastão',k:'Mobilidade',t:85},
    {n:'Mobilidade de quadril e joelho',k:'Mobilidade',t:125},{n:'Alongamento da parte posterior',k:'Estático',t:165},{n:'Alongamento dinâmico de quadril',k:'Dinâmico',t:210},
    {n:'Perna lateral, costas retas',k:'Dinâmico',t:230},{n:'Alongamento deitado',k:'Estático',t:255},{n:'Sentado entre os pés, peito aberto',k:'Estático',t:300},
    {n:'Alongamento de adutor',k:'Estático',t:350},{n:'Posição de cócoras',k:'Mobilidade',t:375},{n:'Escápula e torção de coluna',k:'Mobilidade',t:415},{n:'Torção deitada',k:'Mobilidade',t:435}
  ];const END=490;CHS.forEach((c,i)=>{c.e=(CHS[i+1]||{t:END}).t;c.d=c.e-c.t});
  const G=[
    {n:'Reabilitar',txt:'Treino com orientação individual, alinhado ao seu profissional de saúde. Começamos por mobilidade e alongamento, no seu ritmo.',ord:[0,1,2,3,4,9,8,7]},
    {n:'Saúde e movimento',txt:'Movimento no dia a dia: soltar, mobilizar e alongar antes de treinar, para o corpo trabalhar melhor.',ord:[0,1,2,3,4,8,10,11]},
    {n:'Performar',txt:'Preparo para o seu esporte: liberação, mobilidade e alongamento dinâmico antes da prática.',ord:[0,2,3,5,6,10,11,12]}
  ];
  const SPORTS=['Beach tennis','Jiu-jitsu','Futebol','CrossFit','Musculação','Outro'];
  let g=1,sport=-1,order=G[1].ord,i=0,rem=0,running=false,timer=null;
  const knob=$('#gknob'),fill=$('#gfill'),txt=$('#gtxt'),stops=$$('.gstops button'),steps=$('#steps'),v=$('#wv'),vid=$('.vid'),bar=$('#wbar'),head=$('#shead'),tm=$('#stime'),go=$('#sgo'),nx=$('#snext');
  const fmt=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
  /* vídeo: só acompanha. A contagem da ficha roda sozinha, então nunca trava. */
  function ensure(){return new Promise(r=>{if(v.readyState>0)return r();if(!v.src)v.src=v.dataset.src;v.preload='auto';const ok=()=>r();v.addEventListener('loadedmetadata',ok,{once:true});setTimeout(ok,2500)})}
  async function seekTo(t,play){await ensure();try{v.currentTime=t;if(play)await v.play()}catch(e){}}
  function mark(){$$('li',steps).forEach((l,k)=>l.classList.toggle('on',k===i&&(running||rem<CHS[order[i]].d)))}
  function paint(){const c=CHS[order[i]];tm.textContent=fmt(rem);$('#snow').textContent=`${i+1}. ${c.n}`;bar.style.width=((1-rem/c.d)*100)+'%';const l=$$('li',steps)[i];if(l){const em=$('em',l);em.textContent=fmt(running||rem<c.d?rem:c.d)}}
  function setI(k,seek,play){i=k;rem=CHS[order[k]].d;mark();paint();if(seek)seekTo(CHS[order[k]].t,play)}
  function tick(){if(!running)return;rem-=.25;if(rem<=0){if(i<order.length-1){setI(i+1,true,true)}else{finish();return}}paint()}
  function start(){if(running)return;running=true;go.textContent='Pausar';vid.classList.add('playing');mark();seekTo(v.currentTime<CHS[order[i]].t||v.currentTime>=CHS[order[i]].e?CHS[order[i]].t:v.currentTime,true);timer=setInterval(tick,250);track('ficha_iniciar',{g:G[g].n})}
  function pause(){running=false;clearInterval(timer);v.pause();vid.classList.remove('playing');go.textContent='Continuar'}
  function finish(){pause();go.textContent='Refazer ficha';rem=0;paint();bar.style.width='100%';setI(0,true,false);go.textContent='Refazer ficha';track('ficha_concluida')}
  function render(){
    pause();go.textContent='Iniciar ficha';
    head.textContent=`Ficha: ${G[g].n}${sport>=0&&sport<5?', antes de '+SPORTS[sport].toLowerCase():''}`;
    steps.innerHTML='';order.forEach((ci,k)=>{const c=CHS[ci],li=document.createElement('li');li.innerHTML=`<b>${k+1}. ${c.n}</b><small>${c.k}</small><em>${fmt(c.d)}</em>`;li.addEventListener('click',()=>{setI(k,true,true);if(!running)start();vid.scrollIntoView({behavior:REDUCED?'auto':'smooth',block:'center'})});steps.appendChild(li)});
    i=0;rem=CHS[order[0]].d;tm.textContent=fmt(order.reduce((s,ci)=>s+CHS[ci].d,0));bar.style.width='0';
  }
  go.addEventListener('click',()=>{if(running)pause();else if(go.textContent==='Refazer ficha'){render();start()}else start()});
  $('#wplay').addEventListener('click',()=>{if(!running)start()});
  v.addEventListener('click',()=>{running?pause():start()});
  nx.addEventListener('click',()=>{if(i<order.length-1){setI(i+1,true,running)}else finish()});
  function setG(k,silent){g=k;const pct=k*50;knob.style.left=pct+'%';fill.style.width=pct+'%';knob.setAttribute('aria-valuenow',k);stops.forEach((b,n)=>b.classList.toggle('on',n===k));txt.style.opacity=0;setTimeout(()=>{txt.textContent=G[k].txt;txt.style.opacity=1},160);order=G[k].ord;render();if(!silent)track('objetivo',{g:G[k].n})}
  const tr=$('.gtrack');let drag=false;
  const fromX=x=>{const r=tr.getBoundingClientRect();return clamp(Math.round((x-r.left)/r.width*2),0,2)};
  const live=x=>{const r=tr.getBoundingClientRect(),p=clamp((x-r.left)/r.width,0,1);knob.style.transition='none';fill.style.transition='none';knob.style.left=p*100+'%';fill.style.width=p*100+'%'};
  tr.addEventListener('pointerdown',e=>{drag=true;tr.setPointerCapture(e.pointerId);live(e.clientX)});
  tr.addEventListener('pointermove',e=>{if(drag)live(e.clientX)});
  tr.addEventListener('pointerup',e=>{if(drag){drag=false;knob.style.transition='';fill.style.transition='';setG(fromX(e.clientX))}});
  knob.addEventListener('keydown',e=>{if(e.key==='ArrowRight')setG(clamp(g+1,0,2));if(e.key==='ArrowLeft')setG(clamp(g-1,0,2))});
  stops.forEach(b=>b.addEventListener('click',()=>setG(+b.dataset.g)));
  const sp=$('#sports');SPORTS.forEach((s,k)=>{const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=s;b.addEventListener('click',()=>{sport=sport===k?-1:k;$$('.chip',sp).forEach((c,n)=>c.classList.toggle('on',n===sport));window.QSTATE.sport=sport>=0?s:'';render();track('esporte',{s})});sp.appendChild(b)});
  window.QSTATE=window.QSTATE||{};Object.defineProperty(QSTATE,'goal',{get:()=>G[g].n});
  new IntersectionObserver((es,o)=>{if(es[0].isIntersecting){v.preload='metadata';if(!v.src)v.src=v.dataset.src;o.disconnect()}},{rootMargin:'400px'}).observe($('#sheet'));
  setG(1,true);
})();

/* ---------- Monte seu plano ---------- */
(function(){
  const S={freq:3,plan:0,slots:{},step:1,started:false,inj:0};
  const steps=$$('.step'),prog=$$('#prog i'),next=$('#next'),back=$('#back'),passe=$('#passe');
  const sparkCv=$('#spark'),sx=sparkCv.getContext('2d');let sparks=[];
  const begin=()=>{if(!S.started){S.started=true;track('iniciar_simulador')}};
  /* faísca nas anilhas */
  function sizeSp(){const r=sparkCv.getBoundingClientRect();sparkCv.width=r.width*2;sparkCv.height=r.height*2}
  function burst(x,y){for(let i=0;i<22;i++){const a=Math.random()*6.283,s=Math.random()*3+1;sparks.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1.2,a:1})}}
  (function loop(){if(sparks.length){sx.clearRect(0,0,sparkCv.width,sparkCv.height);sx.save();sx.scale(2,2);sparks=sparks.filter(p=>p.a>0);sparks.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.12;p.a-=.03;sx.fillStyle=`rgba(238,205,96,${p.a})`;sx.fillRect(p.x,p.y,2.4,2.4)});sx.restore()}requestAnimationFrame(loop)})();
  /* anilhas */
  const bw=$('#barwrap'),pl=$$('.pl',bw),centers=[55,86,119,154,191];
  function setFreq(n,fx){
    S.freq=n;pl.forEach(p=>{const on=+p.dataset.n<=n,was=p.classList.contains('act');p.classList.toggle('act',on);if(on&&!was){p.style.animation='none';void p.offsetWidth;p.style.animation=''}});
    const b=$('#fv');b.textContent=n;b.animate([{transform:'scale(1.35)'},{transform:'scale(1)'}],{duration:350,easing:'cubic-bezier(.22,1,.36,1)'});
    $('#fl').textContent=n===1?'vez por semana':'vezes por semana';
    if(fx){sizeSp();burst(centers[n-1],75)}
    trimSlots();renderPrice();
  }
  const nearest=x=>{const r=$('.bar',bw).getBoundingClientRect(),px=x-r.left;let k=0,m=1e9;centers.forEach((c,i)=>{const d=Math.abs(c-px);if(d<m){m=d;k=i}});return k+1};
  let dr=false;
  bw.addEventListener('pointerdown',e=>{begin();dr=true;bw.setPointerCapture(e.pointerId);const p=e.target.closest('.pl');setFreq(p?+p.dataset.n:nearest(e.clientX),true)});
  bw.addEventListener('pointermove',e=>{if(!dr)return;const n=nearest(e.clientX);if(n!==S.freq)setFreq(n,true)});
  bw.addEventListener('pointerup',()=>{dr=false});
  /* período: cartões com o valor cheio */
  const TOT=(f,p)=>PLANS[f][p]*[1,3,6][p],MES=[1,3,6];
  const pcs=$$('#pcards .per');
  function renderPrice(){
    pcs.forEach((c,i)=>{$('.pt',c).textContent=brl(TOT(S.freq,i));$('.pm',c).textContent=i?`${MES[i]} meses de ${brl(PLANS[S.freq][i])}`:`1 mês, ${brl(PLANS[S.freq][0])}`;c.classList.toggle('on',i===S.plan);c.setAttribute('aria-checked',i===S.plan)});
    $('#psum').innerHTML=`Você paga <b>${brl(TOT(S.freq,S.plan))}</b> de uma vez, à vista, em espécie, Pix ou transferência.`;
    bw.dataset.plan=S.plan;
  }
  pcs.forEach((c,i)=>c.addEventListener('click',()=>{begin();S.plan=i;renderPrice();track('plano_escolhido',{plano:PLAN_NAMES[i],freq:S.freq,valor:TOT(S.freq,i)})}));
  /* dias e horários */
  const isOpen=(d,h)=>{const s=Math.max(h*60,d===2?390:0);return(OPEN[d]||[]).some(([a,b])=>s>=a&&s+60<=b)};
  const days=$('#days'),hrs=$('#hrs'),sel=[];
  [1,2,3,4,5].forEach(d=>{const b=document.createElement('button');b.type='button';b.dataset.d=d;b.setAttribute('aria-pressed','false');b.innerHTML=`<b>${DAYS[d]}</b>`;b.addEventListener('click',()=>{begin();const i=sel.indexOf(d);if(i>-1){sel.splice(i,1);delete S.slots[d]}else{sel.push(d);if(sel.length>S.freq){const o=sel.shift();delete S.slots[o]}}syncDays()});days.appendChild(b)});
  function trimSlots(){while(sel.length>S.freq){const o=sel.shift();delete S.slots[o]}syncDays()}
  function syncDays(){
    $$('button',days).forEach(b=>{const on=sel.includes(+b.dataset.d);b.classList.toggle('on',on);b.setAttribute('aria-pressed',on)});
    const left=S.freq-sel.length;
    $('#gcount').textContent=left>0?`Escolha mais ${left} ${left===1?'dia':'dias'}`:'Dias escolhidos';
    $('#dayhint').textContent=S.freq===5?'Com 5 vezes, você treina de segunda a sexta.':`Toque em ${S.freq} ${S.freq===1?'dia':'dias'} da semana.`;
    hrs.innerHTML='';
    sel.slice().sort().forEach(d=>{
      const row=document.createElement('label');row.className='hr2';
      const opts=HOURS.filter(h=>isOpen(d,h)).map(h=>`<option value="${h}"${S.slots[d]==h?' selected':''}>${d===2&&h===6?'6h30':h+'h'}</option>`).join('');
      row.innerHTML=`<span>${DAYL[d][0].toUpperCase()+DAYL[d].slice(1)}</span><select><option value="">Escolher horário</option>${opts}</select>`;
      $('select',row).addEventListener('change',e=>{if(e.target.value)S.slots[d]=+e.target.value;else delete S.slots[d];row.classList.toggle('ok',!!e.target.value)});
      row.classList.toggle('ok',!!S.slots[d]);hrs.appendChild(row)});
    next.disabled=S.step===3&&left>0;next.classList.toggle('dis',next.disabled);
  }
  /* passos */
  function show(n){
    S.step=n;steps.forEach(s=>s.classList.toggle('on',+s.dataset.s===n));prog.forEach((p,i)=>p.classList.toggle('on',i<n));
    back.style.visibility=n>1?'visible':'hidden';next.textContent=n===4?'Gerar meu passe':'Continuar';track('passo_'+n);syncDays();
  }
  next.addEventListener('click',()=>{begin();if(S.step<4)show(S.step+1);else finish()});
  back.addEventListener('click',()=>{if(S.step>1)show(S.step-1)});
  $$('#inj button').forEach(b=>b.addEventListener('click',()=>{S.inj=+b.dataset.v;$$('#inj button').forEach(x=>x.classList.toggle('on',x===b))}));
  function msg(forWa){
    const name=$('#fname').value.trim(),v=PLANS[S.freq][S.plan],sl=sel.slice().sort().map(d=>`${DAYS[d]} ${S.slots[d]?S.slots[d]+'h':'horário a combinar'}`).join(', ');
    const l=[name?`Olá! Sou ${name} e quero montar meu plano no Quintal Home Box.`:'Olá! Quero montar meu plano no Quintal Home Box.'];
    if(window.QSTATE?.goal)l.push('Objetivo: '+QSTATE.goal);if(QSTATE?.sport)l.push('Esporte: '+QSTATE.sport);
    l.push('Lesão ou orientação específica: '+(S.inj?'sim, conto no atendimento':'não'),`Frequência: ${S.freq}x por semana`,`Plano: ${PLAN_NAMES[S.plan]}, ${S.plan?MES[S.plan]+' meses de '+brl(v)+', ':''}total ${brl(TOT(S.freq,S.plan))} à vista`,`Dias e horários: ${sl||'a combinar'}`);
    return l.join('\n');
  }
  function finish(){
    steps.forEach(s=>s.classList.remove('on'));$('.nav').hidden=true;$('#skipw').hidden=true;$('.prog').style.opacity=.5;
    passe.hidden=false;const t=$('.ticket',passe);t.classList.remove('st');$('#pmsg').textContent=msg();void t.offsetWidth;t.classList.add('st');
    $('#pwa').href=waLink(msg());track('simulador_concluido',{freq:S.freq,plano:PLAN_NAMES[S.plan],valor:TOT(S.freq,S.plan),slots:Object.keys(S.slots).length});
    passe.scrollIntoView({behavior:REDUCED?'auto':'smooth',block:'center'});
  }
  $('#pwa').addEventListener('click',()=>track('clique_whatsapp',{local:'passe'}));
  $('#pcopy').addEventListener('click',async()=>{const t=msg();try{await navigator.clipboard.writeText(t)}catch(e){const a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();try{document.execCommand('copy')}catch(_){}a.remove()}$('#pcopyt').textContent='Copiado';setTimeout(()=>$('#pcopyt').textContent='Copiar resumo',1800);track('copiar_resumo')});
  $('#predo').addEventListener('click',()=>{passe.hidden=true;$('.nav').hidden=false;$('#skipw').hidden=false;$('.prog').style.opacity=1;show(1)});
  /* tabela legível sem JS */
  $('#ptab tbody').innerHTML=[5,4,3,2,1].map(n=>`<tr><th>${n}x por semana</th>${PLANS[n].map(v=>`<td>${brl(v)}</td>`).join('')}</tr>`).join('');
  window.QSIM=S;
  setFreq(3);show(1);renderPrice();syncDays();
})();

/* ---------- Por dentro: faixas, lightbox, carrossel ---------- */
(function(){
  const A=[{f:'espaco-quintal-a',c:'O espaço do Quintal'},{f:'espaco-quintal-b',c:'Cantinho do Quintal'},{f:'giro-pelo-espaco-aula-experimental',v:1,c:'Giro pelo espaço'},{f:'aluno-treino-a',c:'Treino no Quintal'},{f:'aluno-treino-b',c:'Treino no Quintal'},{f:'reel-aluno-c',v:1,c:'Aluno em treino'}];
  const B=[{f:'foto-treino-a',c:'Treino no Quintal'},{f:'aluno-treino-c',c:'Treino no Quintal'},{f:'reel-swing-balance',v:1,c:'Treino em movimento'},{f:'aluno-treino-d',c:'Treino no Quintal'},{f:'aluno-treino-e',c:'Treino no Quintal'},{f:'reel-curto-f',v:1,c:'Treino em movimento'}];
  const C=[{f:'reel-resumo-aluno-a',v:1,c:'Resumo da semana'},{f:'reel-resumo-aluno-b',v:1,c:'Resumo da semana'},{f:'reel-presente-sequencia',v:1,c:'Sequência de treino'},{f:'reel-aluno-d',v:1,c:'Aluno em treino'},{f:'reel-aluno-e',v:1,c:'Aluno em treino'},{f:'reel-treino-g',v:1,c:'Treino no Quintal'},{f:'reel-peito-e-ombros',v:1,c:'Peito e ombros'},{f:'aluno-corda-a',c:'Treino com corda'},{f:'aluno-corda-b',c:'Treino com corda'}];
  const strips=[];
  [['#stA',A],['#stB',B]].forEach(([id,list])=>{const el=$(id);list.forEach(m=>el.appendChild(mkMedia(m,'tile')));const st={el,dir:+el.dataset.dir,pos:0,paused:false,vis:false,t:0};strips.push(st);
    const hold=()=>{st.paused=true;clearTimeout(st.t)};const rel=()=>{clearTimeout(st.t);st.t=setTimeout(()=>{st.pos=el.scrollLeft;st.paused=false},1800)};
    el.addEventListener('pointerdown',hold);el.addEventListener('touchstart',hold,{passive:true});el.addEventListener('pointerup',rel);el.addEventListener('touchend',rel);el.addEventListener('wheel',()=>{hold();rel()},{passive:true});
    new IntersectionObserver(es=>{st.vis=es[0].isIntersecting;if(st.vis&&!st.init){st.init=true;st.pos=st.dir>0?0:el.scrollWidth}}).observe(el);
  });
  (function loop(){strips.forEach(st=>{if(st.vis&&!st.paused&&!LB.open&&!REDUCED){const max=st.el.scrollWidth-st.el.clientWidth;st.pos+=st.dir*.55;if(st.pos<=0){st.pos=0;st.dir=1}else if(st.pos>=max){st.pos=max;st.dir=-1}st.el.scrollLeft=st.pos}});requestAnimationFrame(loop)})();
  const car=$('#car');C.forEach(m=>car.appendChild(mkMedia(m,'cd')));
  const cds=$$('.cd',car);
  new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('cur',e.isIntersecting&&e.intersectionRatio>.7)),{root:car,threshold:[.7]}).observe&&cds.forEach(c=>new IntersectionObserver(es=>es.forEach(e=>c.classList.toggle('cur',e.intersectionRatio>.7)),{root:car,threshold:[.7]}).observe(c));
  // arrasta com o dedo ou mouse
  let dn=false,sx0=0,sl0=0;car.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){dn=true;sx0=e.clientX;sl0=car.scrollLeft;car.style.scrollSnapType='none'}});
  addEventListener('pointermove',e=>{if(dn)car.scrollLeft=sl0-(e.clientX-sx0)});addEventListener('pointerup',()=>{if(dn){dn=false;car.style.scrollSnapType=''}});
  // lightbox
  window.LB={open:false};
  const lb=$('#lb'),lbm=$('#lbm'),lbc=$('#lbc');
  function open(el){
    const f=el.dataset.f,v=el.dataset.v;lbm.innerHTML='';
    if(v){const x=document.createElement('video');x.src=`assets/${f}.mp4`;x.poster=`assets/${f}.jpg`;x.muted=true;x.loop=true;x.playsInline=true;x.controls=true;x.autoplay=true;lbm.appendChild(x)}
    else{const i=new Image();i.src=`assets/${f}.webp`;i.alt=el.dataset.c;lbm.appendChild(i)}
    lbc.textContent=el.dataset.c;lb.hidden=false;LB.open=true;Mascot.setHide(true);track('abrir_midia',{f});
  }
  function close(){lb.hidden=true;LB.open=false;lbm.innerHTML='';Mascot.setHide(false)}
  window.openLB=open;
  document.addEventListener('click',e=>{const t=e.target.closest('.tile,.cd,.m');if(t&&t.dataset.f&&!dnMoved)open(t)});
  let dnMoved=false,mx=0;document.addEventListener('pointerdown',e=>{mx=e.clientX;dnMoved=false});document.addEventListener('pointermove',e=>{if(Math.abs(e.clientX-mx)>8&&e.buttons)dnMoved=true});
  $('#lbx').addEventListener('click',close);lb.addEventListener('click',e=>{if(e.target===lb||e.target===lbm)close()});addEventListener('keydown',e=>{if(e.key==='Escape'&&LB.open)close()});
})();

/* ---------- Quem treina: pilha de fotos e linha do tempo ---------- */
(function(){
  const J=[{f:'jeremias-retrato',c:'Jeremias Pereira'},{f:'jeremias-treino',c:'Jeremias em treino'},{f:'jeremias-formatura-a',c:'Formatura em Educação Física, UFPI'},{f:'jeremias-formatura-b',c:'Formatura, com a família'},{f:'jeremias-formatura-capelo',c:'Dia da formatura'},{f:'jeremias-mural',c:'Jeremias no Quintal'},{f:'jeremias-com-homenageado',c:'Jeremias com um homenageado'},{f:'pessoa-camp-irc',c:'Em evento'}];
  const pile=$('#pile'),cap=$('#pcap');let order=J.map((_,i)=>i);
  const cards=J.map((m,i)=>{const d=document.createElement('div');d.className='pc';const im=new Image();im.src=`assets/${m.f}.webp`;im.alt=m.c;im.loading='lazy';d.appendChild(im);pile.appendChild(d);return d});
  const rot=[0,-4,3,-2,5,-5,2,-3];
  function layout(animate=true){
    order.forEach((ci,pos)=>{const c=cards[ci];c.style.transition=animate?'':'none';c.style.zIndex=20-pos;c.style.opacity=pos>3?0:1;c.style.transform=`translate(${pos?pos*5:0}px,${pos*9}px) rotate(${pos?rot[ci]:0}deg) scale(${1-pos*.045})`});
    cap.textContent=J[order[0]].c;
  }
  layout();
  let sx=0,drag=null;
  pile.addEventListener('pointerdown',e=>{const c=cards[order[0]];if(!e.target.closest('.pc')||e.target.closest('.pc')!==c&&e.target.closest('.pc'))drag=null;sx=e.clientX;drag={c,id:e.pointerId};c.style.transition='none';pile.setPointerCapture(e.pointerId)});
  pile.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-sx;drag.c.style.transform=`translate(${dx}px,0) rotate(${dx/14}deg)`});
  pile.addEventListener('pointerup',e=>{if(!drag)return;const dx=e.clientX-sx,c=drag.c;drag=null;
    if(Math.abs(dx)>60||Math.abs(dx)<4){c.style.transition='transform .5s cubic-bezier(.22,1,.36,1),opacity .4s';c.style.transform=`translate(${Math.abs(dx)<4?-260:Math.sign(dx)*320}px,0) rotate(${Math.sign(dx||-1)*24}deg)`;c.style.opacity=0;setTimeout(()=>{order.push(order.shift());layout(false);requestAnimationFrame(()=>layout(true))},420);track('pilha_jeremias')}
    else layout(true)});
  /* linha do tempo */
  const T=[
    {h:'De um simples home box',p:'A história do Quintal, contada pelo Jeremias.',m:[{f:'historia-do-quintal-jeremias',v:1,k:'v'}]},
    {h:'A turma de antes',p:'Fotos de quem já treinou por aqui.',m:['a','b','c','d','e','f'].map(x=>({f:'turma-antiga-'+x}))},
    {h:'Arraiá do Quintal',p:'O Quintal também é encontro.',m:[{f:'grupo-no-quintal-arraia',k:'sq'}]},
    {h:'Visita ao Macaúba CrossHouse',p:'Registros da visita ao box.',m:['a','b','c'].map(x=>({f:'parceiros-macauba-'+x,k:'sq'}))},
    {h:'Hoje, um studio individual',p:'Poucos alunos por horário e atenção no seu movimento.',m:[]}
  ];
  const tl=$('#tl2'),chs=[];
  T.forEach(t=>{const c=document.createElement('div');c.className='ch';c.innerHTML=`<h4>${t.h}</h4><p>${t.p}</p>`;if(t.m.length){const row=document.createElement('div');row.className='cm';t.m.forEach(m=>{const el=mkMedia(m,'m '+(m.k||''));row.appendChild(el)});c.appendChild(row)}tl.appendChild(c);chs.push(c)});
  const fill=$('#tlfill');
  function upd(){const r=tl.getBoundingClientRect(),p=clamp((innerHeight*.72-r.top)/r.height,0,1);fill.style.height=(p*100)+'%';chs.forEach(c=>c.classList.toggle('on',c.offsetTop+14<p*r.height))}
  addEventListener('scroll',upd,{passive:true});addEventListener('resize',upd);upd();
})();

/* ---------- Pergunte ao Quintal ---------- */
(function(){
  const pr=(n)=>PLANS[n].map((v,i)=>`${PLAN_NAMES[i]} ${brl(v)}`).join(', ');
  const FAQ=[
    ['Quantas pessoas por horário?','Poucas. O Quintal é um studio intimista e o treino é individual. Para saber se há vaga no horário que você quer, chame no WhatsApp.'],
    ['Quanto custa?',`De ${brl(PLANS[1][2])} a ${brl(PLANS[5][0])} por mês, conforme a frequência e o período. Por exemplo, 3x por semana: ${pr(3)}. O valor do período é pago por inteiro, à vista, em espécie, Pix ou transferência. Por exemplo, 3x por semana no trimestral são ${brl(PLANS[3][1]*3)} de uma vez, e no semestral ${brl(PLANS[3][2]*6)}.`],
    ['Posso treinar só 1x por semana?',`Pode. O plano de 1x por semana custa ${pr(1)}, por mês.`],
    ['Quais são os horários?','De segunda a sexta, em aulas de 1 hora. Segunda e quarta: 6h às 12h e 14h às 20h. Terça: 6h30 às 20h. Quinta: 9h às 20h. Sexta: 6h às 12h e 14h às 18h.'],
    ['Serve para reabilitação?','O Quintal trabalha treino com orientação individual, alinhado ao seu profissional de saúde. Conte o seu caso no WhatsApp para o Jeremias te orientar.'],
    ['Onde fica?','Rua Des. Adalberto Correia Lima, 1047, Ininga, Teresina-PI, CEP 64049-680. O botão de rota abre direto no Maps.'],
    ['Tem aula experimental?','Isso o Jeremias confirma direto com você no WhatsApp, (86) 99987-0153.']
  ];
  const chat=$('#chat'),qs=$('#qs');let busy=false;
  const bl=(c,t)=>{const d=document.createElement('div');d.className='bl '+c;if(t)d.textContent=t;chat.appendChild(d);chat.scrollTop=chat.scrollHeight;return d};
  function ask(i,btn){
    if(busy)return;busy=true;btn&&btn.classList.add('used');track('faq',{q:FAQ[i][0]});
    bl('q',FAQ[i][0]);const t=bl('t');t.innerHTML='<i></i><i></i><i></i>';
    setTimeout(()=>{t.className='bl a';t.textContent='';const txt=FAQ[i][1];let k=0;const iv=setInterval(()=>{k+=REDUCED?txt.length:2;t.textContent=txt.slice(0,k);chat.scrollTop=chat.scrollHeight;if(k>=txt.length){clearInterval(iv);busy=false}},16)},750);
  }
  FAQ.forEach((f,i)=>{const b=document.createElement('button');b.type='button';b.textContent=f[0];b.addEventListener('click',()=>ask(i,b));qs.appendChild(b)});
  new IntersectionObserver((es,o)=>{if(es[0].isIntersecting){o.disconnect();setTimeout(()=>ask(0,qs.children[0]),500)}},{threshold:.4}).observe(chat);
})();

/* ---------- Rota animada ---------- */
(function(){
  const p=$('#rp'),d=$('#rd');if(!p)return;const L=p.getTotalLength();let t0=0;
  (function f(n){if(!REDUCED){const k=((n-t0)/5200)%1,pt=p.getPointAtLength(k*L);d.setAttribute('cx',pt.x);d.setAttribute('cy',pt.y)}requestAnimationFrame(f)})(0);
})();

addEventListener('quintal:open',initReveal);
if(REDUCED)setTimeout(initReveal,800);

/* ---------- Cores da logo espalhadas, mais luz e interação ---------- */
(function(){
  // 1. bordas animadas nos botões, com as cores da logo em rodízio
  const SEL='.lk,.chip,.next,.qs button,.sctl button,.cd,.pill,.mind,.per,.days button';
  let n=0;
  function tag(root){$$(SEL,root).forEach(el=>{if(el.classList.contains('bd'))return;el.classList.add('bd');el.dataset.c=n++%5})}
  tag(document);new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(nd=>{if(nd.nodeType===1){if(nd.matches&&nd.matches(SEL)&&!nd.classList.contains('bd')){nd.classList.add('bd');nd.dataset.c=n++%5}tag(nd)}}))).observe(document.body,{childList:true,subtree:true});
  $('#sheet').dataset.c=2;
  // 2. ondas de luz ao tocar
  document.addEventListener('pointerdown',e=>{const el=e.target.closest('.bd');if(!el||el.classList.contains('cd')||el.id==='mind')return;const r=el.getBoundingClientRect(),s=document.createElement('span');s.className='rip';s.style.left=(e.clientX-r.left)+'px';s.style.top=(e.clientY-r.top)+'px';el.appendChild(s);setTimeout(()=>s.remove(),700);navigator.vibrate&&navigator.vibrate(8)},{passive:true});
  // 3. títulos: parte fina e parte grossa
  $$('h2').forEach(h=>{const w=h.textContent.trim().split(/\s+/);if(w.length<2)return;const k=w.length>3?w.length-2:w.length-1;h.innerHTML=`<span class="th">${w.slice(0,k).join(' ')}</span> ${w.slice(k).join(' ')}`});
  // 5. barra de progresso e paralaxe por seção
  const sp=$('#sp'),secs=$$('.sec');let tick=false;
  function onScroll(){if(tick)return;tick=true;requestAnimationFrame(()=>{tick=false;const m=document.documentElement.scrollHeight-innerHeight;sp.style.transform=`scaleX(${m>0?scrollY/m:0})`;secs.forEach(s=>{const r=s.getBoundingClientRect();if(r.bottom<-100||r.top>innerHeight+100)return;$('.bg',s).style.setProperty('--p',((r.top+r.height/2-innerHeight/2)/innerHeight).toFixed(3))})})}
  addEventListener('scroll',onScroll,{passive:true});onScroll();
  // 6. inclinação 3D nas peças ao arrastar o dedo
  $$('.flip,.ticket,.route').forEach(el=>{el.style.transition='transform .5s cubic-bezier(.22,1,.36,1)';
    const mv=e=>{const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(700px) rotateY(${x*14}deg) rotateX(${-y*14}deg)`};
    el.addEventListener('pointermove',mv);el.addEventListener('pointerleave',()=>{el.style.transform=''});el.addEventListener('pointerup',()=>{el.style.transform=''})});
})();
